4.4 Dry Mass to Wet Mass Conversion, and Bioenergetics Prey Category Assignment
To express prey item mass in wet weight (the required unit for Fish Bioenergetics 4.0 inputs), we apply wet/dry mass ratios from McCarthy et al. 2009 and additional literature sources. These ratios are stored in other/outputs/diet/mass_conversion/prey_types_manual_edit.xlsx.
The general approach:

Each unique prey taxon/lifestage in the dataset was manually assigned to one of a set of broader prey type categories (this mapping was done once and is stored in the prey_types sheet of the conversion workbook)
Each prey type category has an associated wet/dry ratio, energy density, and bioenergetics diet-slot category from the literature (stored in the data_validation sheet, columns wet_dry_ratio, energy_density_jg, and PreyCategory_ED)
We join these values to the diet data and compute wet mass as: wm_mg = dm_mg / wet_dry_ratio

Note that the raw PreyCategory field recorded in the source workbooks (retained here as preycat_field) is a field-level classification (origin: terrestrial/aquatic/unknown) and is not the same as the five-category bioenergetics diet-slot scheme used for FB4 inputs (Diet1-5: FishEggs, InvertAquatic_AqOrigin, InvertTerrestrial, InvertTerrestrial_AqOrigin, SalmonEggs). The latter comes from PreyCategory_ED in the conversion workbook, keyed to each prey taxon’s assigned prey_type. All downstream summaries and figures in this chapter use PreyCategory_ED (as preycat), not preycat_field.


Code
dm_convert_prey_types &lt;- read_excel(
  "other/outputs/diet/mass_conversion/prey_types_manual_edit.xlsx",
  sheet = "prey_types", skip = 1
) |&gt;
  select(-notes)

dm_convert_vals &lt;- read_excel(
  "other/outputs/diet/mass_conversion/prey_types_manual_edit.xlsx",
  sheet = "data_validation"
) |&gt;
  filter(!is.na(prey_type))

dm_convert_vals &lt;- left_join(dm_convert_prey_types, dm_convert_vals, by = "prey_type") |&gt;
  filter(!is.na(wet_dry_ratio)) |&gt;
  select(-notes) |&gt;
  rename(prey = unique_diet_prey)

diet &lt;- left_join(diet, dm_convert_vals, by = "prey") |&gt;
  filter(!is.na(wet_dry_ratio)) |&gt;
  mutate(
    wm_mg   = dm_mg / wet_dry_ratio,
    preycat = factor(PreyCategory_ED, levels = c(
      "SalmonEggs", "FishEggs",
      "InvertAquatic_AqOrigin", "InvertTerrestrial_AqOrigin",
      "InvertTerrestrial"
    ))
  )

4.5 Fish Age and Size
We join fish length, weight, and age data to the diet records so that we can disaggregate diet summaries by age class and examine size-related patterns.


Code
fish_ages15 &lt;- read_excel(SCTC2015, sheet = "C 2015 Diet & LW Data") |&gt;
  select(
    river, sample.id, sample.event, spp,
    Weight_g, Length_mm, Age_manual2, sample.event.num,
    `Date...41`, `Site ID`, reach_name
  ) |&gt;
  rename(
    wt_g = Weight_g, len_mm = Length_mm,
    age = Age_manual2,
    date_fish = `Date...41`
  ) |&gt;
  mutate(
    date_fish = anytime::anydate(date_fish),
    wt_g = as.double(wt_g),
    year = "2015"
  ) |&gt;
  filter(spp %in% c("Coho", "Chinook"))

fish_ages16 &lt;- read_excel(SCTC2016, sheet = "C 2016 Diet & LW Data") |&gt;
  select(
    river, sample.id, sample.event, spp,
    Weight_g, Length_mm, Age_manual2, sample.event.num,
    Date, `Site ID`, reach_name
  ) |&gt;
  rename(
    wt_g = Weight_g, len_mm = Length_mm,
    age = Age_manual2,
    date_fish = Date
  ) |&gt;
  mutate(
    date_fish = anytime::anydate(date_fish),
    wt_g = as.numeric(wt_g),
    year = "2016"
  ) |&gt;
  filter(spp %in% c("Coho", "Chinook"))

fish_ages &lt;- bind_rows(fish_ages15, fish_ages16) |&gt;
  mutate(
    spp  = factor(spp, levels = c("Chinook", "Coho")),
    year = as.factor(year),
    age  = as.integer(age)
  ) |&gt;
  filter(!is.na(age), age %in% c(0, 1))

rm(fish_ages15, fish_ages16)

# Join age and size to diet data
diet &lt;- left_join(diet, fish_ages |&gt; select(sample.id, wt_g, len_mm, age),
                  by = "sample.id") |&gt;
  filter(!is.na(age))

4.6 Diet Proportions by Wet Mass
We calculate the proportion of total wet mass contributed by each prey category, at multiple levels of grouping. Results at the fish level (per-fish proportions) are used for summaries; grouped proportions (pooled across fish within a group) are used as bioenergetics model inputs (Chapter 4).
A fish that did not eat a given prey category has no row for that category, not an explicit zero. If left that way, a later group-level average of prop_wm (e.g., mean proportion of salmon eggs in a river/season/species/age group) would be computed only over the fish that did eat that category, rather than over all fish in the group. Category means computed this way do not share a common denominator, and can sum to well over 100% when stacked. We fix this by completing each fish’s record with explicit zero-mass rows for every prey category it did not eat, so every fish contributes to every category’s denominator downstream.


Code
# Per-fish wet mass by prey bioenergetics category
diet_per_fish &lt;- diet |&gt;
  group_by(sample.id, spp, age, year, river, season, preycat) |&gt;
  summarise(wm_mg = sum(wm_mg, na.rm = TRUE), .groups = "drop") |&gt;
  # Explicit zeros for uneaten categories; see note above
  complete(nesting(sample.id, spp, age, year, river, season), preycat, fill = list(wm_mg = 0))

# Per-fish total wet mass (denominator)
fish_totals &lt;- diet_per_fish |&gt;
  group_by(sample.id) |&gt;
  summarise(total_wm_mg = sum(wm_mg), .groups = "drop")

# Per-fish proportions
diet_props &lt;- left_join(diet_per_fish, fish_totals, by = "sample.id") |&gt;
  mutate(prop_wm = wm_mg / total_wm_mg)

4.8 Coarse-Level Subsidy Summary
We collapse prey categories into three coarse groups (terrestrial, freshwater-aquatic, marine/salmon-derived) to facilitate comparison with external literature.


Code
subsidy_map &lt;- tibble(
  preycat = c(
    "InvertTerrestrial", "InvertTerrestrial_AqOrigin",
    "InvertAquatic_AqOrigin",
    "FishEggs", "SalmonEggs"
  ),
  subsidy_class = c(
    "Terrestrial", "Terrestrial (aquatic origin)",
    "Freshwater-aquatic",
    "Marine/salmon-derived", "Marine/salmon-derived"
  )
)

diet_subsidy &lt;- diet_props |&gt;
  left_join(subsidy_map, by = "preycat") |&gt;
  group_by(sample.id, spp, age, year, river, season, subsidy_class) |&gt;
  summarise(prop_wm = sum(prop_wm, na.rm = TRUE), .groups = "drop")

5.4 Simulation Temporal Extents
Each simulation covers the period from the deployment date of one trap-check event to the deployment date of the following event. For the final sampling event of each year, the simulation extends 30 days past the deployment date. Temporal extents are determined from the fishing effort data in the raw Excel workbooks.
The code below derives the temporal extent for each site × year × season. The output is in other/outputs/observed_diet_proportions.csv, which joins temporal extent data to diet proportions. The code is shown to document the logic; set eval: true if regenerating from scratch.


Code
SCTC2015 &lt;- "other/inputs/diet_size_other/2015 EPSCoR SCTC.xlsx"
SCTC2016 &lt;- "other/inputs/diet_size_other/2016_EPSCoR_Aquatic_Ecology_Database.xlsx"

effort2015 &lt;- read_excel(SCTC2015, sheet = "B Fishing Data", skip = 2) |&gt;
  rename(site.id = Site_ID, sample.event = Sample_Event) |&gt;
  select(site.id, Reach, River, sample.event, sample.event.num,
         deploy_dt, collect_dt) |&gt;
  filter(!is.na(sample.event)) |&gt;
  mutate(
    site.id       = as.factor(site.id),
    sample.event  = as.factor(sample.event),
    sample.event.num = as.factor(sample.event.num)
  )

effort2016 &lt;- read_excel(SCTC2016, sheet = "B Fishing Data", skip = 2) |&gt;
  rename(site.id = Site_ID, sample.event = Sample_Event) |&gt;
  select(site.id, Reach, River, sample.event, sample.event.num,
         deploy_dt, collect_dt) |&gt;
  filter(!is.na(sample.event)) |&gt;
  mutate(
    site.id       = as.factor(site.id),
    sample.event  = as.factor(sample.event),
    sample.event.num = as.factor(sample.event.num)
  )

effort &lt;- bind_rows(effort2015, effort2016) |&gt;
  mutate(
    collect_dt = anytime(collect_dt),
    deploy_dt  = anytime(deploy_dt),
    year       = year(collect_dt),
    site       = paste(Reach, River)
  ) |&gt;
  filter(site != "Upper Ptarmigan Creek")

rm(effort2015, effort2016)

# Define temporal extent for each site × year × sampling event
sim_extents_by_site &lt;- effort |&gt;
  group_by(River, site, year, sample.event, sample.event.num) |&gt;
  nest() |&gt;
  mutate(
    season.start = purrr::map_dbl(data, ~min(.$deploy_dt)),
    season.end   = purrr::map_dbl(data, ~min(.$deploy_dt))
  ) |&gt;
  mutate(
    season.start = anytime(season.start),
    season.end   = anytime(season.end)
  ) |&gt;
  arrange(site, year, sample.event)

# End of each season = start of next; final season = start + 30 days
make_extents &lt;- function(df_year, final_event_num) {
  main  &lt;- df_year |&gt;
    mutate(season.end_x = lead(season.end)) |&gt;
    select(-season.end) |&gt;
    filter(sample.event.num != as.factor(final_event_num)) |&gt;
    rename(season.end = season.end_x)
  final &lt;- df_year |&gt;
    filter(sample.event.num == as.factor(final_event_num)) |&gt;
    mutate(season.end = season.start + lubridate::days(30)) |&gt;
    select(-any_of("season.end_x"))
  bind_rows(main, final)
}

t15 &lt;- sim_extents_by_site |&gt; filter(year == 2015)
t16 &lt;- sim_extents_by_site |&gt; filter(year == 2016)

# 2016 Middle Ptarmigan Creek had no 4th visit; assign manually
mpc_2016_3 &lt;- t16 |&gt;
  filter(sample.event == "MPC-2016-3") |&gt;
  mutate(season.end = season.start + lubridate::days(30))

t16_no_mpc &lt;- t16 |&gt;
  filter(sample.event != "MPC-2016-3") |&gt;
  mutate(season.end_x = lead(season.end)) |&gt;
  select(-season.end) |&gt;
  filter(sample.event.num != as.factor(4)) |&gt;
  rename(season.end = season.end_x)

t16_final &lt;- t16 |&gt;
  filter(sample.event.num == as.factor(4), sample.event != "MPC-2016-3") |&gt;
  mutate(season.end = season.start + lubridate::days(30))

sim_extents_by_site &lt;- bind_rows(
  make_extents(t15, 3),
  t16_no_mpc,
  t16_final,
  mpc_2016_3
) |&gt;
  rename(Stream_Name = River, sim.start = season.start, sim.end = season.end) |&gt;
  mutate(
    year   = as.factor(year),
    season = fct_recode(as.factor(sample.event.num),
                        "Early Summer" = "1",
                        "Mid-Summer"   = "2",
                        "Late Summer"  = "3",
                        "Fall"         = "4"),
    days   = round(sim.end - sim.start)
  ) |&gt;
  select(-data)

rm(t15, t16, t16_no_mpc, t16_final, mpc_2016_3)


