6.4 P-value Inputs from Observed Simulations
For projected simulations, we do not fit to a final weight. Instead, we hold the proportion of maximum consumption (p-value) fixed at the mean value estimated from 2015-2016 observed simulations, and also run at ±20% of that mean.
P-values are extracted from the committed FB4 output from Chapter 4.


Code
# Requires committed FB4 output from the observed chapter
fb4_obs &lt;- read.csv(
  "other/FB4_1.1.3_2015_2016.1/FB4_2015_2016_models_new_parameters.csv"
) |&gt;
  clean_names() |&gt;
  rename(Simulation = run_name) |&gt;
  separate(Simulation,
           into = c("year", "season", "site", "spp", "e", "age"),
           sep  = "_", remove = FALSE) |&gt;
  separate(site, into = c("reach", "river1", "river2"), remove = FALSE) |&gt;
  mutate(Stream_Name = paste(river1, river2)) |&gt;
  select(spp, age, year, season, site, reach, initial_w, p_value, Stream_Name)

# Projected simulation period: May 26 – September 4
min_sim_doy &lt;- yday(ymd("2015-05-26"))
max_sim_doy &lt;- yday(ymd("2015-09-04"))
sim_duration &lt;- max_sim_doy - min_sim_doy

# Mean p-value by watershed × species × age
mean_pvals &lt;- fb4_obs |&gt;
  group_by(Stream_Name, spp, age) |&gt;
  summarise(mean_pval = mean(p_value), .groups = "drop")

# Initial weight = mean weight at earliest sampling event per cohort
mean_start_w &lt;- fb4_obs |&gt;
  mutate(season_num = case_when(
    season == "Early Summer" ~ 1,
    season == "Mid-Summer"   ~ 2,
    season == "Late Summer"  ~ 3,
    season == "Fall"         ~ 4
  )) |&gt;
  group_by(Stream_Name, spp, age, site) |&gt;
  slice_min(season_num) |&gt;
  summarise(mean_init_w = mean(initial_w), .groups = "drop")

# Build three consumption scenarios per cohort
init_file_dat &lt;- left_join(mean_start_w, mean_pvals,
                           by = c("Stream_Name", "spp", "age")) |&gt;
  mutate(
    `20plus_pval`  = mean_pval * 1.2,
    `20minus_pval` = mean_pval * 0.8
  ) |&gt;
  pivot_longer(
    cols = c("mean_pval", "20plus_pval", "20minus_pval"),
    names_to  = "consumption_scenario",
    values_to = "value"
  ) |&gt;
  mutate(Simulation = paste0(site, "_", spp, "_Age_", age))

6.5 Simulation Temporal Extents
For projected scenarios, all cohorts share a common simulation window: May 26 to September 4 (Julian days 146–247). This is the earliest date with weight data common across all sites and years, through the earliest final sampling visit plus 30 days.
Diet proportions are replicated across simulation days at the scale of river × species × age (no season grouping, unlike the observed simulations).


Code
# Temporal extent for projected simulations (one row per site × spp × age)
obs_diet_ref &lt;- read.csv("other/outputs/observed_diet_proportions.csv") |&gt;
  group_by(Stream_Name, site, spp, age) |&gt;
  summarise(
    sim.start = as.integer(mean(yday(as.Date(sim.start)))),
    sim.end   = as.integer(mean(yday(as.Date(sim.end)))),
    .groups   = "drop"
  ) |&gt;
  mutate(days = sim.end - sim.start)

diet_prop_proj &lt;- left_join(wm_diet_props, obs_diet_ref,
                            by = c("Stream_Name", "spp", "age")) |&gt;
  mutate(days = as.double(days))

sim_diet_days &lt;- diet_prop_proj[
  rep(seq_len(nrow(diet_prop_proj)), diet_prop_proj[, "days"]), ] |&gt;
  mutate(sim_name = paste0(site, "_", spp, "_Age_", age)) |&gt;
  group_by(sim_name) |&gt;
  mutate(
    SimDay = row_number(),
    doy    = sim.start + SimDay
  )

# Replicate for each scenario period
scenario_periods &lt;- c(
  "rcp60_2030_2039", "rcp85_2030_2039",
  "rcp60_2060_2069", "rcp85_2060_2069",
  "rcp60_2010_2019", "rcp85_2010_2019"
)

sim_diet_days &lt;- map_dfr(scenario_periods, function(sp) {
  sim_diet_days |&gt; mutate(scenario_period = sp)
})

# Join monthly projected temperatures by month extracted from doy
sim_diet_days &lt;- sim_diet_days |&gt;
  mutate(
    date  = as.Date(doy, origin = as.Date("2015-01-01")),
    month = month(date)
  )

proj_temp_monthly &lt;- daily_proj_temps |&gt;
  filter(year == "2016") |&gt;
  select(scenario_period, site, Stream_Name, month, daily_avg_temp) |&gt;
  distinct()

sim_diet_days &lt;- left_join(
  sim_diet_days, proj_temp_monthly,
  by = c("site", "scenario_period", "month", "Stream_Name")
) |&gt;
  rename(avg_temp = daily_avg_temp) |&gt;
  filter(!is.na(avg_temp)) |&gt;
  rename(
    diet1 = FishEggs,
    diet2 = InvertAquatic_AqOrigin,
    diet3 = InvertTerrestrial,
    diet4 = InvertTerrestrial_AqOrigin,
    diet5 = SalmonEggs,
    Temp  = avg_temp
  ) |&gt;
  mutate(diet6 = 0, diet7 = 0, diet8 = 0, diet9 = 0, diet10 = 0) |&gt;
  select(-SimDay) |&gt;
  group_by(sim_name, scenario_period, spp) |&gt;
  mutate(SimDay = row_number()) |&gt;
  ungroup() |&gt;
  mutate(sim_name = paste0(scenario_period, "_", sim_name)) |&gt;
  select(SimDay, Temp, diet1, diet2, diet3, diet4, diet5,
         diet6, diet7, diet8, diet9, diet10, sim_name, spp)

sim_diet_days[is.na(sim_diet_days)] &lt;- 0

7.2 Import 2015-2016 Observed Simulation Results


Code
cols_retain &lt;- c("run_name", "first_day", "last_day", "species_txt",
                 "year", "season", "site", "spp", "age",
                 "initial_w", "final_weight_g", "fit.to", "fit.to.value",
                 "p_value", "total_consumption_g", "cum_cons_pop_g")

old_param_results &lt;- read.csv(
  "other/FB4_1.1.3_2015_2016.1/FB4_2015_2016_models_old_parameters.csv"
) |&gt;
  clean_names() |&gt;
  separate(col = run_name,
           into = c("year", "season", "site", "spp", "agex", "age"),
           sep = "_", remove = FALSE) |&gt;
  select(any_of(cols_retain)) |&gt;
  mutate(parameters = "stewart_ibarra")

new_param_results &lt;- read.csv(
  "other/FB4_1.1.3_2015_2016.1/FB4_2015_2016_models_new_parameters.csv"
) |&gt;
  clean_names() |&gt;
  separate(col = run_name,
           into = c("year", "season", "site", "spp", "agex", "age"),
           sep = "_", remove = FALSE) |&gt;
  select(any_of(cols_retain)) |&gt;
  mutate(parameters = "plumb_moffit")

# Combine and attach simulation julian-day extents
sim_julian_days &lt;- read.csv("other/outputs/observed_diet_proportions.csv") |&gt;
  select(spp, age, site, year, season, sim.start, sim.end) |&gt;
  mutate(
    sim.start = yday(as.Date(sim.start)),
    sim.end   = yday(as.Date(sim.end)),
    run_name  = paste0(year, "_", season, "_", site, "_", spp, "_Age_", age)
  ) |&gt;
  select(sim.start, sim.end, run_name)

results &lt;- bind_rows(old_param_results, new_param_results) |&gt;
  left_join(sim_julian_days, by = "run_name") |&gt;
  mutate(
    scenario             = "observed",
    consumption_scenario = "observed"
  )

